static tls_tcb_t *initial_block_init(ptr_t base, ptr_t *dtv) {
	rtld_image_t *image;
	size_t i;

	for(i = static_dtv_size - 1; i >= 1; i--) {
		image = rtld_image_lookup(i);
		if(!image || !image->tls_memsz)
			continue;

