void
_strided_byte_swap(void *p, npy_intp stride, npy_intp n, int size)
{
    char *a, *b, c = 0;
    int j, m;

    switch(size) {
        case 1: /* no byteswap necessary */
            break;
        case 4:
            for (a = (char*)p; n > 0; n--, a += stride - 1) {
                b = a + 3;
                c = *a; *a++ = *b; *b-- = c;
                c = *a; *a = *b; *b   = c;
            }
            break;
        case 8:
            for (a = (char*)p; n > 0; n--, a += stride - 3) {
                b = a + 7;
                c = *a; *a++ = *b; *b-- = c;
                c = *a; *a++ = *b; *b-- = c;
                c = *a; *a++ = *b; *b-- = c;
                c = *a; *a = *b; *b   = c;
            }
            break;
        case 2:
            for (a = (char*)p; n > 0; n--, a += stride) {
                b = a + 1;
                c = *a; *a = *b; *b = c;
            }
            break;
        default:
            m = size/2;
            for (a = (char *)p; n > 0; n--, a += stride - m) {
                b = a + (size - 1);
                for (j = 0; j < m; j++) {
                    c=*a; *a++ = *b; *b-- = c;
                }
            }
            break;
    }
}


