int txnet777_wtsort(const void *a,const void *b)
{
//#define wt_a (*(struct txnet777_tx **)a)->H.wtsum
//#define wt_b (*(struct txnet777_tx **)b)->H.wtsum
#define wt_a ((struct txnet777_tx *)a)->H.wtsum
