    size = (int32_t)(sizeof(*tx) + (tx->in.numoutputs - 1) * sizeof(*tx->out));
    if ( tx->in.allocsize == 0 )
        return(size);
    if ( size >= tx->in.allocsize && tx->in.allocsize <= 0x10000000 )
