void
putsym(int c1)
{
	char c = c1; /* XXX this hack prevents .o diffs -- remove later */

	switch (c) {
	case '\b':
		backsp();
		return;
	case '\n':
		curx = 1;
		cury++;
		if (cury > tly)
			tly = cury;
		break;
	default:
		if (curx == CO)
			putsym('\n');	/* 1 <= curx <= CO; avoid CO */
		else
			curx++;
	}
	(void) putchar(c);
}

void
putstr(const char *s)
{
	while (*s)
		putsym(*s++);
