			/* filename */
			fname(arg);
			first = 0;
		}
		argc--;
		argv++;
	}

	if (first)
		usage();

	if (iflag)
		terminate(0);

	if (!oflag) {
		if ((tmp = getenv("LIBDIR")) == NULL || strlen(tmp) == 0)
			tmp = PATH_LINTLIB;
		appcstrg(&libsrchpath, tmp);
		findlibs(libs);
		findlibs(deflibs);
	}

	(void)printf("Lint pass2:\n");
	lint2();

	if (oflag)
