                return null;
            }
            return new BigDecimal(new BigDecimal(str).toPlainString());
        } else if (obj instanceof byte[]) {
            return toBigDecimal(toSerializable((byte[]) obj)); // recursive
        } else {
            return new BigDecimal(new BigDecimal(obj.toString()).toPlainString());
