                  ImmutableMap.of(
                      "SOURCE_ROOT", ".",
                      "SRCROOT", ".")));

      targetGroup.getOrCreateFileReferenceBySourceTreePath(
          new SourceTreePath(
              PBXReference.SourceTree.SOURCE_ROOT,
              Paths.get(entitlementsPlistPath),
              Optional.empty()));
    }
